import json
from pathlib import Path


class SauvegardeCorrompue(Exception):
    pass


def sauvegarder(recettes: list[dict], chemin: Path) -> None:
    with open(chemin, "w", encoding="utf-8") as f:
        json.dump(recettes, f, ensure_ascii=False, indent=2)


def charger(chemin: Path) -> list[dict]:
    try:
        texte = chemin.read_text(encoding="utf-8")
    except FileNotFoundError:
        return []                       # premier lancement : cas nominal
    try:
        return json.loads(texte)
    except json.JSONDecodeError as exc:
        raise SauvegardeCorrompue(f"{chemin} illisible : {exc}") from exc


if __name__ == "__main__":
    RECETTES = [
        {"nom": "carbonara", "ingredients": ["pates", "oeufs", "parmesan", "lardons"], "temps_min": 25},
        {"nom": "crème brûlée", "ingredients": ["crème", "oeufs", "sucre"], "temps_min": 50},
    ]
    chemin = Path("recettes.json")

    sauvegarder(RECETTES, chemin)
    assert charger(chemin) == RECETTES          # round-trip exact
    print(chemin.read_text(encoding="utf-8"))   # "crème brûlée" lisible ✓

    assert charger(Path("inexistant.json")) == []

    chemin.write_text(chemin.read_text(encoding="utf-8")[:40], encoding="utf-8")
    try:
        charger(chemin)
    except SauvegardeCorrompue as exc:
        print(f"OK, détecté : {exc}")
```

Points de conception :

- Absent → `[]` : l'appelant n'a AUCUN cas particulier à gérer au premier lancement.
- Corrompu → exception : rendre `[]` ici serait catastrophique (au prochain `sauvegarder`, la sauvegarde de l'utilisateur serait écrasée par du vide). La règle : ne jamais transformer une corruption en état vide silencieux.
- Sans `ensure_ascii=False`, le fichier contiendrait `\u00e8` à la place de `è` — valide mais illisible pour un humain qui édite sa sauvegarde.
